<?php
/**
 * Slide-page chrome: "Tattoo Studio Melbourne" label, social icon rail, slide counter, scroll cue.
 * The numbered counter buttons are generated by assets/js/navigation.js from the real number of slides.
 *
 * @package inko-melbourne
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}
$ik_socials = inko_socials();
?>
<div class="ik-label" aria-hidden="true"><p>Tattoo<br>Studio<br>Melbourne</p></div>
<aside class="ik-rail" aria-label="<?php esc_attr_e( 'Follow us', 'inko-melbourne' ); ?>">
	<b class="ik-rail__t"><?php esc_html_e( 'Follow Us', 'inko-melbourne' ); ?></b>
	<?php foreach ( array( 'instagram', 'facebook', 'tiktok', 'youtube' ) as $ik_key ) : ?>
		<a href="<?php echo esc_url( $ik_socials[ $ik_key ]['url'] ); ?>" aria-label="<?php echo esc_attr( $ik_socials[ $ik_key ]['label'] ); ?>"<?php echo '#' !== $ik_socials[ $ik_key ]['url'] ? ' target="_blank" rel="noopener"' : ''; ?>><img src="<?php echo esc_url( $ik_socials[ $ik_key ]['icon'] ); ?>" width="96" height="96" alt=""></a>
	<?php endforeach; ?>
</aside>
<ol class="ik-count" aria-label="<?php esc_attr_e( 'Sections', 'inko-melbourne' ); ?>"></ol>
<button class="ik-cue" type="button" data-go="next" aria-label="<?php esc_attr_e( 'Next section', 'inko-melbourne' ); ?>"><span><?php esc_html_e( 'Scroll', 'inko-melbourne' ); ?></span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 5l7 7 7-7M5 12l7 7 7-7"/></svg></button>
